#include <iostream>
#include <string>
using namespace std;

int main() {
    int marks;
    cin >> marks;
    string base;
    if (marks >= 90) {
        base = "A";
    } else if (marks >= 80) {
        base = "B";
    } else if (marks >= 70) {
        base = "C";
    } else if (marks >= 60) {
        base = "D";
    } else {
        base = "F";
    }
    string grade = base;
    if (base != "F" && marks != 100) {
        int d = marks % 10;
        if (d >= 7) {
            grade = base + "+";
        } else if (d <= 2) {
            grade = base + "-";
        }
    }
    cout << "Marks: " << marks << endl;
    cout << "Grade: " << grade << endl;
    return 0;
}

