    cin >> a >> b >> op;
    switch (op) {
        case '+':
            cout << "Result: " << fixed << setprecision(2) << a + b << endl;
            break;
        case '-':
            cout << "Result: " << fixed << setprecision(2) << a - b << endl;
            break;
        case '*':
            cout << "Result: " << fixed << setprecision(2) << a * b << endl;
            break;
        case '/':
            if (b == 0) {
                cout << "Error: division by zero" << endl;
            } else {
                cout << "Result: " << fixed << setprecision(2) << a / b << endl;
            }
            break;
        default:
            cout << "Invalid operator" << endl;
            break;
    }
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    const double BASE = 5000.0;
    int age, zone, noClaim;
    cin >> age >> zone >> noClaim;
    if (zone < 1 || zone > 3) {
        cout << "Invalid zone" << endl;
        return 0;
    }
    double ageFactor;
    if (age < 25) {
        ageFactor = 1.5;
    } else if (age <= 60) {
        ageFactor = 1.0;
    } else {
        ageFactor = 1.3;
    }
    int zonePct;
    if (zone == 1) {
        zonePct = 0;
    } else if (zone == 2) {
        zonePct = 10;
    } else {
        zonePct = 25;
    }
    double afterZone = BASE * ageFactor * (1 + zonePct / 100.0);
    int discPct;
    if (noClaim >= 5) {
        discPct = 15;
    } else if (noClaim >= 3) {
        discPct = 10;
    } else if (noClaim >= 1) {
        discPct = 5;
    } else {
        discPct = 0;
    }
    double finalPremium = afterZone * (1 - discPct / 100.0);
    cout << fixed << setprecision(2);
    cout << "Base premium: " << BASE << endl;
    cout << "Age factor: " << ageFactor << endl;
    cout << "Zone load: " << zonePct << "%" << endl;
    cout << "Premium after zone: " << afterZone << endl;
    cout << "No claim discount: " << discPct << "%" << endl;
    cout << "Final premium: " << finalPremium << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    int speed, limit;
    char vclass, repeat;
    cin >> speed >> limit >> vclass >> repeat;
    int over = speed - limit;
    double base = 0.0;
    double mult = 1.0;
    double total = 0.0;
    if (over > 0) {
        if (over <= 10) {
            base = 300;
        } else if (over <= 25) {
            base = 800;
        } else if (over <= 50) {
            base = 1500;
        } else {
            base = 2500;
        }
        if (vclass == 'C') {
            mult = 1.0;
        } else if (vclass == 'B') {
            mult = 1.2;
        } else {
            mult = 1.5;
        }
        total = base * mult;
        if (repeat == 'Y') {
            total = total * 1.5;
        }
    }
    string suspended = "no";
    if (over > 50 || (repeat == 'Y' && over > 25)) {
        suspended = "yes";
    }
    cout << "Speed: " << speed << endl;
    cout << "Limit: " << limit << endl;
    cout << "Over by: " << over << endl;
    cout << fixed << setprecision(2);
    cout << "Base fine: " << base << endl;
    cout << "Class multiplier: " << mult << endl;
    cout << "Repeat offender: " << repeat << endl;
    cout << "Total fine: " << total << endl;
    cout << "License suspended: " << suspended << endl;
    return 0;
}

