#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    int dayCode, hours;
    char grade;
    cin >> dayCode >> hours >> grade;
    if (dayCode < 1 || dayCode > 3) {
        cout << "Invalid day code" << endl;
        return 0;
    }
    if (grade != 'A' && grade != 'B' && grade != 'C') {
        cout << "Invalid grade" << endl;
        return 0;
    }
    string dayName;
    double mult;
    if (dayCode == 1) {
        dayName = "Weekday";
        mult = 1.0;
    } else if (dayCode == 2) {
        dayName = "Weekend";
        mult = 1.5;
    } else {
        dayName = "Holiday";
        mult = 2.0;
    }
    double baseRate;
    if (grade == 'A') {
        baseRate = 300;
    } else if (grade == 'B') {
        baseRate = 250;
    } else {
        baseRate = 200;
    }
    int ot = 0;
    if (hours > 8) {
        ot = hours - 8;
    }
    if (dayCode == 3 && hours > 0 && ot < 4) {
        ot = 4;
    }
    double rate = baseRate * mult;
    double pay = ot * rate;
    cout << "Day type: " << dayName << endl;
    cout << "Hours worked: " << hours << endl;
    cout << "Overtime hours: " << ot << endl;
    cout << fixed << setprecision(2);
    cout << "Rate per hour: " << rate << endl;
    cout << "Overtime pay: " << pay << endl;
    return 0;
}

